package com.bank.sysdesign;

import java.math.BigDecimal;
import java.util.logging.*;

public class InterviewDemo {
    private static final Logger log = Logger.getLogger("SysDesign");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // STEP 1 — clarify requirements
        RequirementsAnalyzer req = new RequirementsAnalyzer();
        req.addFunctional("Customer can transfer money between accounts");
        req.addNonFunctional("Balance must never be wrong (strong consistency)");
        req.estimate(10_000_000L);   // 10 million transfers/day
        req.print();

        // STEP 2 — high-level design
        HighLevelDesign hld = new HighLevelDesign();
        hld.addComponent("API Gateway", "auth + rate limit");
        hld.addComponent("TransferService", "atomic debit+credit");
        hld.addComponent("PostgreSQL", "source of truth");
        hld.addComponent("Kafka", "async notifications");
        hld.print();

        // STEP 3 — deep dive: atomic transfer
        AccountRepository repo = new AccountRepository();
        repo.save(new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        repo.save(new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
        TransferService service = new TransferService(repo);
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"), "idem-key-1");
        // retry with same key must NOT double-transfer
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"), "idem-key-1");

        log.info(() -> "Rajesh final balance: " + repo.findById("SAV2001").getBalance());
        log.info(() -> "Priya final balance: " + repo.findById("CUR3001").getBalance());

        // STEP 4 — trade-offs
        TradeoffReport report = new TradeoffReport();
        report.add("Consistency vs Availability", "Chose strong consistency (money)");
        report.add("Sync vs Async", "Transfer sync, notification async via Kafka");
        report.print();
    }
}

