class RequirementsAnalyzer {
    private static final Logger log = Logger.getLogger("SysDesign");
    private final java.util.List<String> functional = new java.util.ArrayList<>();
    private final java.util.List<String> nonFunctional = new java.util.ArrayList<>();
    private long avgTps, peakTps;

    void addFunctional(String s) { functional.add(s); }
    void addNonFunctional(String s) { nonFunctional.add(s); }

    void estimate(long dailyTransfers) {
        this.avgTps = dailyTransfers / 86_400L;
        this.peakTps = avgTps * 5;   // assume 5x peak
    }

    void print() {
        log.info("STEP 1 — Requirements clarified");
        functional.forEach(f -> log.info(() -> "  functional: " + f));
        nonFunctional.forEach(n -> log.info(() -> "  non-functional: " + n));
        log.info(() -> "  avg TPS=" + avgTps + ", peak TPS=" + peakTps);
    }
}

